questions.question:
נתונות הגדרה של פונקציית `main` והגדרה של פונקציה `f` בה הושמט טיפוס החזרה:
```cpp
___ f() {
    static int x = 0;
    return x;
}
void main() { f() = 5; }
```
מה צריך להיות הטיפוס שהפונקציה `f` מחזירה כדי שהתוכנית תעבור קומפילציה?

מה מדפיסה התכנית?
```cpp
#include <iostream>
class X {
public:
    int f;
};
void g(X x) { x.f = 5; }
void main() {
    X x;
    x.f = 3;
    g(x);
    std::cout << x.f;
}
```

מה מדפיסה התכנית?
```cpp
#include <iostream>
class X {
public: X(int n) { std::cout << n; }
};
X a(1);
void main() {
    X a(2);
    X b(3);
}
```

אילו שורות גורמות לשגיאת קומפילציה במחלקה הבאה:
```cpp
1. class X {
2. public:
3.     X() : x(1) {}
4.     X(int a) { x = 1; }
5.     X(int a, int b) { }
6.     const int x;
7. };
```

אילו שורות גורמות לשגיאת קומפילציה בקטע הקוד הבא:
```cpp
1. class X {
2.     friend class Y;
3.     int a;
4.     void f(Y y) { y.a = 1; }
5. };
6. class Y {
7.     int a;
8.     void f(X x) { x.a = 1; }
9. };
```

מה צריך להיכתב בשורה 3 כדי שהתכנית הבאה תתקמפל ותדפיס 1:
```cpp
#include <iostream>
class X {
public:
    X& f() { return _____; }
};
void main() {
    X x;
    std::cout << (&x == &x.f());
}
```

בתכנית מוגדרת מחלקה `X`. מה צריך לעשות כדי שקטע הקוד הבא יעבור קומפילציה:
```cpp
X x;
2 << x;
```

בתכנית מוגדרת מחלקה `X`. מה צריך לעשות כדי שקטע הקוד הבא יעבור קומפילציה
```cpp
X x;
x(5);
```

מה נכון לגבי השדה `f` במחלקה `X`:
```cpp
class X {
public:
    int f;
};
```

מה נכון לגבי השדה `f` במחלקה `X`:
```cpp
class X {
private:
    int f;
};
```

מה מדפיסה התכנית הבאה:
```cpp
#include <iostream>
class X {
public:
    void f() { std:: cout << 1; }
};
class Y : public X {
public:
    virtual void f() { std::cout << 2; }
};
void main() {
    Y y;
    X *p = &y;
    p->f();
}
```

מה מדפיסה התכנית הבאה:
```cpp
#include <iostream>
class X {
public:
    X() { std::cout << 1; }
    ~X() { std::cout << 2; }
};
class Y : public X{
public:
    Y() { std::cout << 3; }
    ~Y() { std::cout << 4; }
};
void main() {
    X *x = new Y;
}
```

